"""ROM-free tests using this pilot's own generated C bytes, not ROM bytes."""
import unittest
from pointer_helper_pilot import split_pool,helper_trace,terminator_offset,SHARED

# Generated by the lawful Clang diagnostic from pointer_helper.c.
GENERATED=bytes.fromhex('10402de914409fe50010a0e16520a0e30400a0e1c3cbfeeb0400a0e11080bde8b4cb0d02')


class PointerHelperTests(unittest.TestCase):
    def test_return_is_fixed_not_opaque_callee_result(self):
        rows,pool=split_pool(GENERATED)
        for result in (0,1,0xffffffff,0xdeadbeef):
            self.assertEqual(helper_trace(rows,pool,call_result=result)['return'],SHARED)

    def test_incoming_r1_overwritten_and_0x65_is_vararg(self):
        rows,pool=split_pool(GENERATED)
        for incoming in (0,0xffffffff,0x1234):
            self.assertEqual(helper_trace(rows,pool,incoming_r1=incoming)['call'],[SHARED,0x5000,0x65])

    def test_pool_is_data_and_stack_is_restored(self):
        rows,pool=split_pool(GENERATED)
        self.assertEqual(len(rows),8)
        result=helper_trace(rows,pool)
        self.assertEqual(result['sp'],0x8000)
        self.assertEqual(len(result['stack_writes']),2)
        with self.assertRaises(ValueError):split_pool(GENERATED[:-4]+bytes(4))

    def test_unapproved_call_cannot_execute(self):
        rows,pool=split_pool(GENERATED)
        rows=[(pc,op,'#0x1234' if op=='bl' else args) for pc,op,args in rows]
        with self.assertRaises(ValueError):helper_trace(rows,pool)

    def test_wrapper_termination_math_is_not_a_64_byte_guard(self):
        self.assertEqual(terminator_offset(28,0xffffffff),28)
        self.assertEqual(terminator_offset(100,0xffffffff),100)
        self.assertEqual(terminator_offset(8,8),7)
        self.assertIsNone(terminator_offset(0,0))
        self.assertEqual(terminator_offset(-1,0xffffffff),0xfffffffe)


if __name__=='__main__':unittest.main()
